// Networks whose regular tasks are switched off (18.10.2026): DLive closed; DatPiff and Shazam wait for the owner's word.
// Their icons stay for the admin panel and for what was done there; the pages of a worker do not offer them.
const CLOSED_PLATFORMS_LIST = ['dlive', 'datpiff', 'shazam'];

// ── Premium state cache ──
// Visibility (admin or feature flag) + counter (active premium actions count)
// rarely change. Sidebar fires on every page render; dashboard fires on its
// own load. Without coalescing, /dashboard would issue 4 round-trips.
// In-memory TTL 30s + inflight-promise dedup → at most 1 pair of fetches per
// 30s window per browser tab. Server-side counter is also cached 30s globally,
// so this layer mostly eliminates HTTP overhead, not SQL.
//
// Use: const { visible, count } = await getPremiumState();
// Bust on actions that change visibility (rare): bustPremiumStateCache().
const _premiumStateCache = { data: null, ts: 0, inflight: null };
const PREMIUM_STATE_TTL_MS = 30 * 1000;

async function getPremiumState() {
  const now = Date.now();
  if (_premiumStateCache.data && (now - _premiumStateCache.ts) < PREMIUM_STATE_TTL_MS) {
    return _premiumStateCache.data;
  }
  if (_premiumStateCache.inflight) return _premiumStateCache.inflight;
  _premiumStateCache.inflight = (async () => {
    const [v, c] = await Promise.all([
      fetch('/api/premium/visibility', { credentials: 'same-origin' }).then(r => r.json()).catch(() => ({ ok: false, visible: false })),
      fetch('/api/premium/counter',    { credentials: 'same-origin' }).then(r => r.json()).catch(() => ({ ok: false, count: 0 })),
    ]);
    const data = {
      visible: !!(v && v.ok && v.visible),
      count: (c && c.ok) ? (c.count || 0) : 0,
    };
    _premiumStateCache.data = data;
    _premiumStateCache.ts = Date.now();
    _premiumStateCache.inflight = null;
    return data;
  })();
  return _premiumStateCache.inflight;
}

function bustPremiumStateCache() {
  _premiumStateCache.data = null;
  _premiumStateCache.ts = 0;
  _premiumStateCache.inflight = null;
}
